import Foundation

// MARK: - Data model
/// The bundled per diem dataset (`Resources/cost-data.json`), generated by
/// `scripts/build-cost-data.py` from U.S. government publications.

struct CostData: Decodable {
    let meta: Meta
    let locations: [CostLocation]

    struct Meta: Decodable {
        let currency: String
        let generatedAt: String
        let sources: [Source]
    }

    struct Source: Decodable, Equatable {
        let id: String          // "gsa" or "dos"
        let name: String
        let publisher: String
        let effective: String   // yyyy-MM-dd
        let url: String
        let page: String
    }
}

/// One place with published rates. Rates are whole U.S. dollars, as published.
struct CostLocation: Decodable, Identifiable, Hashable {
    let id: String
    let name: String
    let country: String
    /// U.S. state code for GSA locations ("TX").
    let region: String?
    let regionName: String?
    let aliases: [String]
    /// Which publication the rates come from: "gsa" or "dos".
    let source: String
    /// When this location's rates took effect, yyyy-MM-dd.
    let effective: String
    /// Covers every day of the year exactly once; a season may wrap past Dec 31.
    let seasons: [Season]

    struct Season: Decodable, Hashable {
        let start: MonthDay
        let end: MonthDay
        let lodgingPerNight: Int
        let mealsPerDay: Int

        func contains(_ day: MonthDay) -> Bool {
            start <= end ? (start <= day && day <= end) : (day >= start || day <= end)
        }
    }

    enum CodingKeys: String, CodingKey {
        case id, name, country, region, regionName, aliases, source, effective, seasons
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(String.self, forKey: .id)
        name = try c.decode(String.self, forKey: .name)
        country = try c.decode(String.self, forKey: .country)
        region = try c.decodeIfPresent(String.self, forKey: .region)
        regionName = try c.decodeIfPresent(String.self, forKey: .regionName)
        aliases = try c.decodeIfPresent([String].self, forKey: .aliases) ?? []
        source = try c.decode(String.self, forKey: .source)
        effective = try c.decode(String.self, forKey: .effective)
        seasons = try c.decode([Season].self, forKey: .seasons)
    }

    /// "Cancun, Mexico", "Austin, TX".
    var displayName: String {
        if let region { return "\(name), \(region)" }
        if country == "United States" { return name }
        return "\(name), \(country)"
    }

    /// The season a calendar day falls in. February 29 uses February 28's
    /// rates: the sources only list non-leap years.
    func season(on date: Date, calendar: Calendar) -> Season? {
        let parts = calendar.dateComponents([.month, .day], from: date)
        guard let month = parts.month, var day = parts.day else { return nil }
        if month == 2 && day == 29 { day = 28 }
        let key = MonthDay(month: month, day: day)
        return seasons.first { $0.contains(key) }
    }
}

/// A day of the year without a year, decoded from "MM-DD".
struct MonthDay: Decodable, Hashable, Comparable {
    let month: Int
    let day: Int

    init(month: Int, day: Int) {
        self.month = month
        self.day = day
    }

    init(from decoder: Decoder) throws {
        let text = try decoder.singleValueContainer().decode(String.self)
        let parts = text.split(separator: "-").compactMap { Int($0) }
        guard parts.count == 2, (1...12).contains(parts[0]), (1...31).contains(parts[1]) else {
            throw DecodingError.dataCorrupted(.init(codingPath: decoder.codingPath,
                                                    debugDescription: "Expected MM-DD, got \(text)"))
        }
        self.init(month: parts[0], day: parts[1])
    }

    static func < (a: MonthDay, b: MonthDay) -> Bool {
        (a.month, a.day) < (b.month, b.day)
    }
}

// MARK: - Store

/// Loads the dataset once and answers lookups and searches. Fully offline.
final class CostDataStore {
    let meta: CostData.Meta
    let locations: [CostLocation]
    private let byID: [String: CostLocation]
    private let index: [(location: CostLocation, name: String, aliases: [String], all: String)]

    /// The dataset bundled with the app, or nil if it's missing or unreadable
    /// (the Trips screens then fall back to a typed-in total).
    static let shared: CostDataStore? = try? CostDataStore(bundle: Bundle(for: CostDataStore.self))

    static let resourceName = "cost-data"

    convenience init(bundle: Bundle, resource: String = CostDataStore.resourceName) throws {
        guard let url = bundle.url(forResource: resource, withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        try self.init(data: Data(contentsOf: url))
    }

    init(data: Data) throws {
        let decoded = try JSONDecoder().decode(CostData.self, from: data)
        meta = decoded.meta
        locations = decoded.locations
        byID = Dictionary(decoded.locations.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
        index = decoded.locations.map { location in
            let name = Self.fold(location.name)
            let aliases = location.aliases.map(Self.fold)
            let all = ([name] + aliases + [location.country, location.region ?? "", location.regionName ?? ""]
                .map(Self.fold)).joined(separator: " ")
            return (location, name, aliases, all)
        }
    }

    func location(id: String) -> CostLocation? {
        byID[id]
    }

    func source(for location: CostLocation) -> CostData.Source? {
        meta.sources.first { $0.id == location.source }
    }

    /// Places whose name, aliases, country or state contain every word of
    /// `query`, ignoring case and accents ("cancun" finds "Cancún"). Best
    /// matches first: name starts with the first word, then name contains
    /// it, then the rest (country or state matches).
    func search(_ query: String, limit: Int = 8) -> [CostLocation] {
        let words = Self.fold(query).split(separator: " ").map(String.init)
        guard let first = words.first else { return [] }

        var matches: [(rank: Int, location: CostLocation)] = []
        for entry in index where words.allSatisfy({ entry.all.contains($0) }) {
            let rank: Int
            if entry.name.hasPrefix(first) || entry.aliases.contains(where: { $0.hasPrefix(first) }) {
                rank = 0
            } else if entry.name.contains(first) || entry.aliases.contains(where: { $0.contains(first) }) {
                rank = 1
            } else {
                rank = 2
            }
            matches.append((rank, entry.location))
        }
        return matches
            .sorted {
                ($0.rank, $0.location.name, $0.location.country, $0.location.id)
                    < ($1.rank, $1.location.name, $1.location.country, $1.location.id)
            }
            .prefix(limit)
            .map(\.location)
    }

    /// Lowercased, accent-free, punctuation turned into single spaces.
    static func fold(_ text: String) -> String {
        let folded = text.folding(options: [.caseInsensitive, .diacriticInsensitive, .widthInsensitive],
                                  locale: Locale(identifier: "en_US_POSIX"))
        let spaced = folded.unicodeScalars.map { CharacterSet.alphanumerics.contains($0) ? Character($0) : " " }
        return String(spaced).split(separator: " ").joined(separator: " ")
    }

    // MARK: Dates

    /// Parses the dataset's yyyy-MM-dd dates as a calendar day.
    static func date(fromDay text: String) -> Date? {
        dayParser.date(from: text)
    }

    /// "Aug 1, 2024" in the user's locale, for a yyyy-MM-dd day.
    static func displayDay(_ text: String) -> String {
        guard let date = date(fromDay: text) else { return text }
        return dayDisplay.string(from: date)
    }

    private static let dayParser: DateFormatter = {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(identifier: "UTC")
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter
    }()

    private static let dayDisplay: DateFormatter = {
        let formatter = DateFormatter()
        formatter.timeZone = TimeZone(identifier: "UTC")
        formatter.dateStyle = .medium
        formatter.timeStyle = .none
        return formatter
    }()
}
